(()=>{window.__qaWrite=null;(async()=>{try{
localStorage.setItem('xray:qa-sentinel', 'written-by-18a');
const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('xray-qa-sentinel',1);
  r.onupgradeneeded=()=>r.result.createObjectStore('s',{keyPath:'k'});
  r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
await new Promise((resolve,reject)=>{const tx=db.transaction('s','readwrite');
  tx.objectStore('s').put({k:'sentinel',v:'written-by-18a',at:new Date().toISOString()});
  tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}});
window.__qaWrite={wrote:true,localStorageKeys:Object.keys(localStorage).length};
}catch(e){window.__qaWrite={wrote:false,error:String(e)}}})();return 'writing sentinels'})()
